  static func known(_ query: String) -> String? {
    let text = query.lowercased().components(separatedBy: .whitespacesAndNewlines).joined()
    if let zone = single(text) { return zone }
    let parts = text.components(separatedBy: CharacterSet(charactersIn: "、,，;；/|·"))
    guard parts.count > 1, let first = parts.first.flatMap(single), parts.allSatisfy({ single($0) == first }) else { return nil }
    return first
  }

  private static func single(_ text: String) -> String? {
    if let zone = aliases[text] { return zone }
    if text.hasPrefix("中国"), text.count > 2 { return single(String(text.dropFirst(2))) }
    if text.hasSuffix("市") || text.hasSuffix("省") { return aliases[String(text.dropLast())] }
    return nil
  }
